#[pymethods]
impl PyConnect {
    fn data_source(
        slf: Bound<'_, Self>,
        kind: PyDataSource,
        config: Bound<'_, PyAny>,
    ) -> PyResult<Py<Self>> {
        let fields = data_source_config_yaml(kind, config)?;
        {
            let mut this = slf.borrow_mut();
            this.plugin = Some(connect_plugin_data_source(kind));
            this.fields = fields;
            this.maybe_persist()?;
        }
        Ok(slf.unbind())
    }
    fn data_sink(
        slf: Bound<'_, Self>,
        kind: PyDataSink,
        config: Bound<'_, PyAny>,
    ) -> PyResult<Py<Self>> {
        let fields = data_sink_config_yaml(kind, config)?;
        {
            let mut this = slf.borrow_mut();
            this.plugin = Some(connect_plugin_data_sink(kind));
            this.fields = fields;
            this.maybe_persist()?;
        }
        Ok(slf.unbind())
    }
    fn schema_sink(
        slf: Bound<'_, Self>,
        kind: PySchemaSink,
        config: Bound<'_, PyAny>,
    ) -> PyResult<Py<Self>> {
        let fields = schema_sink_config_yaml(kind, config)?;
        {
            let mut this = slf.borrow_mut();
            this.plugin = Some(connect_plugin_schema_sink(kind));
            this.fields = fields;
            this.maybe_persist()?;
        }
        Ok(slf.unbind())
    }
    fn name(slf: Bound<'_, Self>, value: String) -> PyResult<Py<Self>> {
        {
            let mut this = slf.borrow_mut();
            this.name = Some(value);
            this.maybe_persist()?;
        }
        Ok(slf.unbind())
    }
}

